const rows=$input.first().json.values,cfg=$('Sheet settings').first().json;
if(!Array.isArray(rows)||!Array.isArray(rows[0]))throw new Error('Sheet returned no header row.');
const header=rows[0].map(x=>String(x).trim().toLowerCase()),cols=header.map((x,i)=>x==='email'?i:-1).filter(x=>x>=0);
if(cols.length!==1)throw new Error('The source range must have exactly one email header.');
const emails=new Set();
for(const row of rows.slice(1)){const raw=row[cols[0]];if(raw===undefined||String(raw).trim()==='')continue;const email=String(raw).trim().toLowerCase();if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)||email.length>254)throw new Error('A nonempty row contains an invalid email format. Correct the source before paid validation.');emails.add(email);}
if(emails.size>cfg.maxUniqueEmails)throw new Error('Unique email limit exceeded before validation requests. Narrow the source range.');
if(emails.size===0)throw new Error('No emails to validate.');
return [...emails].map(email=>({json:{email}}));

const expected=new Set($('Normalize email rows').all().map(i=>i.json.email)),seen=new Set(),results=[];
const allowed=new Set(['valid','invalid','catch-all','unknown','spamtrap','abuse','do_not_mail']);
for(const i of $input.all()){const r=i.json,email=typeof r.address==='string'?r.address.trim().toLowerCase():'';if(r.error||!expected.has(email)||seen.has(email)||!allowed.has(r.status))throw new Error('Validation response is missing, duplicated, unexpected or an error. No report is marked complete.');seen.add(email);results.push({email,status:r.status,subStatus:typeof r.sub_status==='string'?r.sub_status:'',needsReview:r.status!=='valid'});}
if(seen.size!==expected.size)throw new Error('Not all requested addresses have results.');
const cell=v=>{let s=String(v);if(/^[=+@-]/.test(s.replace(/^[\s\u0000-\u001f\u007f]*/,'')))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};
const csv=['email,status,sub_status,needs_review',...results.map(r=>[r.email,r.status,r.subStatus,r.needsReview].map(cell).join(','))].join('\r\n')+'\r\n';
return [{json:{complete:true,checked:results.length,needsReview:results.filter(r=>r.needsReview).length,results,csv,fileName:'email-validation-report.csv',consentVerified:false}}];

const settings=$input.first().json;
if(settings.spreadsheetId==='YOUR_SPREADSHEET_ID'||typeof settings.spreadsheetId!=='string'||!/^[A-Za-z0-9_-]+$/.test(settings.spreadsheetId))throw new Error('Set your Google spreadsheet ID.');
if(typeof settings.range!=='string'||settings.range.length>150)throw new Error('Set an explicit bounded A1 range.');
const m=settings.range.match(/^(?:'[^']+'|[A-Za-z0-9_ -]+)!([A-Z]+)([1-9][0-9]*):([A-Z]+)([1-9][0-9]*)$/);
if(!m)throw new Error('Use Sheet!A1:B100 syntax with explicit start and end cells.');
const col=s=>[...s].reduce((n,c)=>n*26+c.charCodeAt(0)-64,0);
const firstCol=col(m[1]),lastCol=col(m[3]),firstRow=Number(m[2]),lastRow=Number(m[4]);
if(![firstCol,lastCol,firstRow,lastRow].every(Number.isSafeInteger)||firstCol>lastCol||firstRow>lastRow||lastRow-firstRow+1>1000||lastCol-firstCol+1>26||lastCol>18278||lastRow>10000000)throw new Error('Use a range of at most 1000 rows and 26 columns within Sheets bounds.');
if(!Number.isSafeInteger(settings.maxUniqueEmails)||settings.maxUniqueEmails<1||settings.maxUniqueEmails>100)throw new Error('maxUniqueEmails must be between 1 and 100.');
return [{json:{spreadsheetId:settings.spreadsheetId,range:settings.range,maxUniqueEmails:settings.maxUniqueEmails}}];
